    if (left == node && right != null) {
      parent.setLeft(right);
      node.setParent(right);
      right.setParent(parent);
    } else if (right == node && left != null) {
      parent.setRight(left);
      node.setParent(left);
      left.setParent(parent);
    }

    return parent;
  }

private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> parent = node.parent;
    TreeNode<T> grandParent = parent.parent;
    TreeNode<T> greatGrandParent = grandParent.parent;

    // Rotate the node and parents
    node.parent = grandParent;
    grandParent.parent = node;

    // Rotate the great-grandparent
    if (greatGrandParent != null) {
      greatGrandParent.parent = greatGrandParent == node.parent ? node : greatGrandParent.parent;
    }

    return parent;
  }

