/**
 * Formats a logging event to a writer.
 * @param event logging event to be formatted.
 */
public String format(final LoggingEvent event) {
    // Create a StringBuilder to hold the formatted event
    StringBuilder builder = new StringBuilder();

    // Get the event timestamp and format it to a string
    long timestamp = event.getTimeStamp();
    Date date = new Date(timestamp);
    String dateString = date.toString();

    // Append the timestamp to the StringBuilder
    builder.append(dateString);

    // Get the event level and append it to the StringBuilder
    Level level = event.getLevel();
    builder.append(level.toString());

    // Get the event message and append it to the StringBuilder
    String message = event.getMessage();
    builder.append(message);

    // Get the event logger's name and append it to the StringBuilder
    String loggerName = event.getLoggerName();
    builder.append(loggerName);

    // Get the event thread's name and append it to the StringBuilder
    String threadName = event.getThreadName();
    builder.append(threadName);

    // Get the event category and append it to the StringBuilder
    String category = event.getCategory();
    builder.append(category);

    // Get the event subcategory and append it to the StringBuilder
    String subcategory = event.getSubcategory();
    builder.append(subcategory);

    // Get the event running time and append it to the StringBuilder
    long runningTime = event.getRunTime();
    builder.append(runningTime);

    // Get the event hash code and append it to the StringBuilder
    int hashCode = event.hashCode();
    builder.append(hashCode);

    // Get the event message byteness and append it to the StringBuilder
    ByteUtils.toString(event.getRawMessage());
    builder.append(" bytes");

    // Get the event ndc and append it to the StringBuilder
    NestedDiagnosticContext ndc = event.getNDC();
    builder.append(ndc.getDiagnosticContext());

    // Get the event category bytes and append it to the StringBuilder
    CategoryBytes categoryBytes = event.getCategoryBytes();
    builder.append(categoryBytes.toString());

    // Get the event location information and append it to the StringBuilder
    LocationInfo locationInfo = event.getLocationInfo();
    builder.append(locationInfo.toString());

    // Get the event properties and append it to the StringBuilder
    Properties properties = event.getProperties();
    builder.append(properties.toString());

    // Get the event context stack and append it to the StringBuilder
    Vector<String> contextStack = event.getContextStack();
    builder.append(contextStack.toString());

    // Return the formatted event as a string
    return builder.toString();
}

public String format(final LoggingEvent event){
    // format the logging event
    return event.getMessage().formatMessage();
}

public static void format(final LoggingEvent event) {
    // LoggingEvent is a complex object, so we need to extract the relevant information first
    String message = event.getMessage();
    String level = event.getLevel().toString();
    if (event.getException() != null) {
        message += " [" + event.getException().toString() + "]";
    }
    String loggerName = event.getLoggerName();
    String timestamp = event.getTimeStamp().toString();
    String threadName = event.getThreadName();

    // Now we can format the logging event as a string
    StringBuilder result = new StringBuilder();
    result.append(timestamp);
    result.append(" [");
    result.append(threadName);
    result.append("] ");
    result.append(loggerName);
    result.append(": ");
    result.append(level);
    result.append(": ");
    result.append(message);
    result.append(System.lineSeparator());
    return result.toString();
}

