private static int getClosestPrime(int capacity, int[] primeCapacities) {
    int minDistance = Integer.MAX_VALUE;
    int closestPrime = -1;
    for (int prime : primeCapacities) {
        if (prime >= capacity) {
            int distance = Math.abs(prime - capacity);
            if (distance < minDistance) {
                minDistance = distance;
                closestPrime = prime;
            }
        }
    }
    return closestPrime;
