        while (k > 0 && less(k, parent(k))) {
            exchange(k, parent(k));
            k = parent(k);
        }
    }

    protected E less(int i, int j) {
        return heap.get(i).compareTo(heap.get(j));
    }

    protected int parent(int i) {
        return i / 2;
    }

