    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }
    if (!path.contains("/") && !relativePath.contains("/")) {
        return path + relativePath;
    }
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");
    if (pathComponents.length < relativePathComponents.length) {
        throw new IllegalArgumentException("Relative path cannot be longer than path: " + relativePath);
    }
    String[] resultComponents = new String[pathComponents.length - relativePathComponents.length + 1];
    System.arraycopy(pathComponents, 0, resultComponents, 0, resultComponents.length);
    for (int i = 0; i < relativePathComponents.length; i++) {
        if (".".equals(relativePathComponents[i])) {
            continue;
        } else if ("..".equals(relativePathComponents[i])) {
            resultComponents[resultComponents.length - 1] = null;
            System.arraycopy(resultComponents, 0, resultComponents, 1, resultComponents.length - 1);
            resultComponents[0] = null;
        } else {
            resultComponents[i] = relativePathComponents[i];
        }
    }
    String result = String.join("/", resultComponents);
    return result.isEmpty() ? "/" : result;
}

