public static String applyRelativePath(String path, String relativePath){
    if (path == null || relativePath == null) {
        throw new NullPointerException("Path and relativePath must not be null");
    }
    if (path.isEmpty() || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Path and relativePath must not be empty");
    }
    char separator = '/';
    String[] pathComponents = path.split(String.valueOf(separator));
    String[] relativePathComponents = relativePath.split(String.valueOf(separator));
    if (relativePathComponents.length == 0) {
        return path;
    }
    if (relativePathComponents[0].equals(".")) {
        return path;
    }
    if (relativePathComponents[0].equals("..")) {
        return pathComponents[pathComponents.length - 2] + separator + relativePath.substring(2);
    }
    return getChildPath(path, relativePath);
}
private static String getChildPath(String path, String relativePath) {
    Deque<String> pathComponents = new ArrayDeque<>();
    pathComponents.addAll(Arrays.asList(path.split("/")));
    Deque<String> relativePathComponents = new ArrayDeque<>();
    relativePathComponents.addAll(Arrays.asList(relativePath.split("/")));
    while (!relativePathComponents.isEmpty()) {
        String component = relativePathComponents.pop();
        if (component.equals(".")) {
            continue;
        } else if (component.equals("..")) {
            pathComponents.pop();
        } else {
            pathComponents.push(component);
        }
    }
    return String.join("/", pathComponents);
}

