    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            // parse the line into a ThreadSnapshot object
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(line);
            // check if the thread snapshot's timestamp falls within the given time ranges
            boolean withinTimeRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (threadSnapshot.getTimestamp() >= timeRange.getStartTime() && threadSnapshot.getTimestamp() <= timeRange.getEndTime()) {
                    withinTimeRange = true;
                    break;
                }
            }
            if (withinTimeRange) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
	List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
	try (BufferedReader br = new BufferedReader(new FileReader(file))) {
		String line;
		while ((line = br.readLine()) != null) {
			ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);
			if (threadSnapshot != null) {
				threadSnapshots.add(threadSnapshot);
			}
		}
	}

	// Filter thread snapshots based on time ranges
	List<ThreadSnapshot> filteredThreadSnapshots = new ArrayList<>();
	for (ThreadSnapshot threadSnapshot : threadSnapshots) {
		for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
			if (threadSnapshot.getTimestamp() <= timeRange.getEndTime() && threadSnapshot.getTimestamp() >= timeRange.getStartTime()) {
				filteredThreadSnapshots.add(threadSnapshot);
				break;
			}
		}
	}
	return filteredThreadSnapshots;
}

// Parse a single thread snapshot from the given line of text
private static ThreadSnapshot parseThreadSnapshot(String line) {
	String[] fields = line.split(",");
	if (fields.length < 3) {
		return null;
	}
	long timestamp = Long.parseLong(fields[0]);
	String threadName = fields[1];
	long threadId = Long.parseLong(fields[2]);
	List<StackTraceElement> stackTrace = new ArrayList<>();
	for (int i = 3; i < fields.length; i++) {
		String methodName = fields[i];
		stackTrace.add(new StackTraceElement(methodName));
	}
	return new ThreadSnapshot(timestamp, threadName, threadId, stackTrace);
}

