     if ( file == null || ( timeRanges != null && timeRanges.isEmpty ( ) ) ) {
          throw new IllegalArgumentException ( "Invalid input received" );
     }

     Long totalSize = file.length ( );
     List<ThreadSnapshot> snapshots = new ArrayList<> ( );

     for ( ProfileAnalyzeTimeRange timeRange : timeRanges ) {

          // throw exception if start or end time of the time range is out of bounds
          if ( timeRange.getStart ( ) < 0 || timeRange.getEnd ( ) >= totalSize ) {
               throw new IllegalArgumentException ( "Time range is out of bounds" );
          }

          // read the bytes from the file for the current time range
          RandomAccessFile raf = new RandomAccessFile ( file, "r" );
          raf.seek ( timeRange.getStart ( ) );
          byte[] bytes = new byte[(int) ( timeRange.getEnd ( ) - timeRange.getStart ( ) )];
          raf.readFully ( bytes );

          // decode the bytes to create the thread snapshot
          ThreadSnapshot snapshot = decodeBytesToThreadSnapshot ( bytes );
          snapshots.add ( snapshot );

          // close the file and free the random access loader
          raf.close ( );
     }

     return snapshots;
