public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split(",");
            if (parts.length < 4) {
                continue;
            }
            long timestamp = Long.parseLong(parts[0]);
            long duration = Long.parseLong(parts[1]);
            long cpuTime = Long.parseLong(parts[2]);
            long monitorEnterTime = Long.parseLong(parts[3]);
            if (timeRanges.stream().filter(range -> range.isInRange(timestamp)).findAny().isPresent()) {
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(timestamp, duration, cpuTime, monitorEnterTime);
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    return threadSnapshots;
}
